// Concatenates migrations + seed into supabase/setup.sql for a one-time paste into the
// Supabase SQL editor, and records the versions so `supabase db push` won't re-run them.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(fileURLToPath(import.meta.url));
const files = readdirSync(join(root, "migrations")).filter((f) => f.endsWith(".sql")).sort();
const parts = [
  "-- GENERATED by supabase/bundle.mjs. Do not edit; edit the migrations instead.",
  "-- Paste into Supabase dashboard → SQL Editor → New query → Run. Run once on an empty project.",
  "begin;",
];
for (const f of files) parts.push(`\n-- ===== ${f} =====\n`, readFileSync(join(root, "migrations", f), "utf8"));
parts.push("\n-- ===== seed.sql =====\n", readFileSync(join(root, "seed.sql"), "utf8"));
parts.push(`
-- Record migration history so the Supabase CLI treats these as applied.
create schema if not exists supabase_migrations;
create table if not exists supabase_migrations.schema_migrations (version text primary key, statements text[], name text);
insert into supabase_migrations.schema_migrations (version, name) values
${files.map((f) => `  ('${f.split("_")[0]}', '${f.replace(/^\d+_/, "").replace(/\.sql$/, "")}')`).join(",\n")}
on conflict (version) do nothing;

commit;
`);
writeFileSync(join(root, "setup.sql"), parts.join("\n"));
console.log(`setup.sql: ${files.length} migrations + seed`);
